public class Main {
    static int n, q;
    static int[] pOrig;
    static ArrayList<Integer>[] adj;
    static int[] tin, tout, nodeOfTin;
    static int timer = 0;
    static int[][] up;
    static final int LOG = 18;
    static boolean[] isActive;
    static TreeSet<Integer> activeTins;
    static FenwickTree bit;

    static class FenwickTree {
        int size;
        int[] tree;

        FenwickTree(int size) {
            this.size = size;
            this.tree = new int[size + 2];
        }

        void add(int i, int delta) {
            for (; i <= size; i += i & -i) {
                tree[i] += delta;
            }
        }

        // Soma no intervalo [l, r]
        void addRange(int l, int r, int delta) {
            add(l, delta);
            add(r + 1, -delta);
        }

        // Consulta pontual em i
        int query(int i) {
            int sum = 0;
            for (; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }

    static void dfs(int u, int p) {
        tin[u] = ++timer;
        nodeOfTin[timer] = u;
        up[0][u] = p;
        for (int j = 1; j < LOG; j++) {
            up[j][u] = up[j - 1][up[j - 1][u]];
        }

        for (int v : adj[u]) {
            dfs(v, u);
        }
        tout[u] = timer;
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        String token = sc.next();
        if (token == null) return;
        n = Integer.parseInt(token);

        pOrig = new int[n + 1];
        adj = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }

        int[] degree = new int[n + 1];
        for (int i = 2; i <= n; i++) {
            pOrig[i] = sc.nextInt();
            adj[pOrig[i]].add(i);
            degree[pOrig[i]]++;
        }

        tin = new int[n + 1];
        tout = new int[n + 1];
        nodeOfTin = new int[n + 1];
        up = new int[LOG][n + 1];

        dfs(1, 0);

        isActive = new boolean[n + 1];
        activeTins = new TreeSet<>();
        bit = new FenwickTree(n);

        // O rei (1) está sempre ativo.
        // Outros nós estão ativos se e somente se possuem subordinados na árvore original.
        isActive[1] = true;
        for (int i = 2; i <= n; i++) {
            if (degree[i] > 0) {
                isActive[i] = true;
            }
        }

        for (int i = 1; i <= n; i++) {
            if (isActive[i]) {
                activeTins.add(tin[i]);
                bit.addRange(tin[i], tout[i], 1);
            }
        }

        q = sc.nextInt();
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < q; i++) {
            int type = sc.nextInt();
            if (type == 1) {
                int v = sc.nextInt();
                int k = sc.nextInt();

                int p = pOrig[v];
                int target = bit.query(tin[p]) - k + 1;

                int curr = p;
                for (int j = LOG - 1; j >= 0; j--) {
                    int anc = up[j][curr];
                    if (anc != 0 && bit.query(tin[anc]) >= target) {
                        curr = anc;
                    }
                }
                sb.append(curr).append("\n");
            } else {
                int v = sc.nextInt();
                if (!isActive[v]) {
                    continue;
                }

                // Desativa todos os nós ativos na subárvore de v (exceto v)
                while (true) {
                    Integer nextTin = activeTins.higher(tin[v]);
                    if (nextTin == null || nextTin > tout[v]) {
                        break;
                    }
                    int u = nodeOfTin[nextTin];
                    activeTins.remove(nextTin);
                    isActive[u] = false;
                    bit.addRange(tin[u], tout[u], -1);
                }
            }
        }

        System.out.print(sb.toString());
    }
}
